            nBuf0 = aPool.Store(eOc, OStringToOUString(t, eSrcChar));

            aPool << nBuf0;
        }
    }

    for( nPass = 0 ; nPass < nCnt && aStack.HasMoreTokens() ; nPass++ )
        aStack >> eParam[ nPass ];

    if (nPass < nCnt)
        // Adapt count to reality. All sort of binary crap is possible.
        nCnt = static_cast<sal_uInt8>(nPass);

