            nBuf0 = aPool.Store( 1900.0 );
            aPool << ocOpen;
        }
            break;
        case ocChoose:
        {// 1. Parameter ++
            if (nCnt >= 1)
                IncToken( eParam[ nCnt - 1 ] );
        }
            break;
        case ocFind:
        case ocHLookup:
        case ocVLookup:
        {// last parameter ++
            IncToken( eParam[ 0 ] );
        }
            break;
        case ocMid:
        case ocReplace:
        {// 2. Parameter ++
